27. export class ProblemStream extends Stream {
28.   private _problems: BunyanRecord[] = [];
29. 
30.   readable: boolean;
31. 
32.   writable: boolean;
33. 
34.   constructor() {
35.     super();
36.     this.readable = false;
37.     this.writable = true;
