65. type ZodShortenedIssue =
66.   | null
67.   | string
68.   | string[]
69.   | {
70.       [key: string]: ZodShortenedIssue;
71.     };
72. 
73. export function prepareZodIssues(input: unknown): ZodShortenedIssue {
74.   if (!isPlainObject(input)) {
75.     return null;
76.   }
77. 
78.   let err: null | string | string[] = null;
79.   // v8 ignore else -- TODO: add test #40625
80.   if (isArray(input._errors, isString)) {
81.     if (input._errors.length === 1) {
82.       err = input._errors[0];
83.     } else if (input._errors.length > 1) {
84.       err = input._errors;
85.     } else {
86.       err = null;
87.     }
88.   }
89.   delete input._errors;
90. 
91.   if (isEmptyObject(input)) {
92.     return err;
93.   }
94. 
95.   const output: Record<string, ZodShortenedIssue> = {};
96.   const entries = Object.entries(input);
97.   for (const [key, value] of entries.slice(0, 3)) {
98.     const child = prepareZodIssues(value);
99.     // v8 ignore else -- TODO: add test #40625
100.     if (child !== null) {
101.       output[key] = child;
102.     }
103.   }
104. 
105.   if (entries.length > 3) {
106.     output.___ = `... ${entries.length - 3} more`;
107.   }
108. 
109.   return output;
110. }
