112. export function prepareZodError(err: ZodError): Record<string, unknown> {
113.   Object.defineProperty(err, 'message', {
114.     get: () => 'Schema error',
115.     /* v8 ignore start -- TODO: drop set? */
116.     set: () => {
117.       /* intentionally empty */
118.     },
119.     // v8 ignore stop -- TODO: drop set? */
120.   });
121. 
122.   return {
123.     message: err.message,
124.     stack: err.stack,
125.     issues: prepareZodIssues(err.format()),
126.   };
127. }
