129. export default function prepareError(err: Error): Record<string, unknown> {
130.   if (err instanceof ZodError) {
131.     return prepareZodError(err);
132.   }
133. 
134.   const response: Record<string, unknown> = {
135.     ...err,
136.   };
137. 
138.   // Required as message is non-enumerable
139.   if (!response.message && err.message) {
140.     response.message = err.message;
141.   }
142. 
143.   // Required as stack is non-enumerable
144.   if (!response.stack && err.stack) {
145.     response.stack = err.stack;
146.   }
147. 
148.   if (err instanceof AggregateError) {
149.     response.errors = err.errors.map((error) => prepareError(error));
150.   }
151. 
152.   // handle rawExec error
153.   if (err instanceof ExecError && isNonEmptyObject(err.options?.env)) {
154.     const env = Object.keys(err.options.env);
155.     response.options = { ...err.options, env };
156.   }
157. 
158.   // handle got error
159.   if (err instanceof HttpError) {
160.     const options: Record<string, unknown> = {
161.       headers: structuredClone(err.options.headers),
162.       url: err.options.url?.toString(),
163.       hostType: err.options.context.hostType,
164.     };
165.     response.options = options;
166. 
167.     options.username = err.options.username;
168.     options.password = err.options.password;
169.     options.method = err.options.method;
170.     options.http2 = err.options.http2;
171. 
172.     // v8 ignore else -- TODO: add test #40625
173.     if (err.response) {
174.       response.response = {
175.         statusCode: err.response.statusCode,
176.         statusMessage: err.response.statusMessage,
177.         body:
178.           err.name === 'TimeoutError'
179.             ? undefined
180.             : structuredClone(err.response.body),
181.         headers: structuredClone(err.response.headers),
182.         httpVersion: err.response.httpVersion,
183.         retryCount: err.response.retryCount,
184.       };
185.     }
186.   }
187. 
188.   return response;
189. }
