191. type NestedValue = unknown[] | object;
192. 
193. function isNested(value: unknown): value is NestedValue {
194.   return isArray(value) || isObject(value);
195. }
196. 
197. export function sanitizeValue(
198.   value: unknown,
199.   seen = new WeakMap<NestedValue, unknown>(),
200. ): any {
201.   if (isString(value)) {
202.     return sanitize(sanitizeUrls(value));
203.   }
204. 
205.   if (isDate(value)) {
206.     return value;
207.   }
208. 
209.   if (isFunction(value)) {
210.     return '[function]';
211.   }
212. 
213.   if (isBuffer(value)) {
214.     return '[content]';
215.   }
216. 
217.   if (isError(value)) {
218.     const err = prepareError(value);
219.     return sanitizeValue(err, seen);
220.   }
221. 
222.   if (isArray(value)) {
223.     const length = value.length;
224.     const arrayResult = Array(length);
225.     seen.set(value, arrayResult);
226.     for (let idx = 0; idx < length; idx += 1) {
227.       const val = value[idx];
228.       arrayResult[idx] =
229.         isNested(val) && seen.has(val)
230.           ? seen.get(val)
231.           : sanitizeValue(val, seen);
232.     }
233.     return arrayResult;
234.   }
235. 
236.   if (isObject(value)) {
237.     const objectResult: Record<string, any> = {};
238.     seen.set(value, objectResult);
239.     for (const [key, val] of Object.entries<any>(value)) {
240.       let curValue: any;
241.       if (!val) {
242.         curValue = val;
243.       } else if (redactedFields.includes(key)) {
244.         // Do not mask/sanitize secrets templates
245.         if (isString(val) && regEx(/^{{\s*secrets\..*}}$/).test(val)) {
246.           curValue = val;
247.         } else {
248.           curValue = '***********';
249.         }
250.       } else if (contentFields.includes(key)) {
251.         curValue = '[content]';
252.       } else if (key === 'secrets') {
253.         curValue = {};
254.         Object.keys(val).forEach((secretKey) => {
255.           curValue[secretKey] = '***********';
256.         });
257.       } else {
258.         curValue = seen.has(val) ? seen.get(val) : sanitizeValue(val, seen);
259.       }
260. 
261.       const sanitizedKey = sanitizeValue(key, seen);
262.       objectResult[sanitizedKey] = curValue;
263.     }
264. 
265.     return objectResult;
266.   }
267. 
268.   return value;
269. }
