271. export function withSanitizer(streamConfig: bunyan.Stream): bunyan.Stream {
272.   if (streamConfig.type === 'rotating-file') {
273.     throw new Error("Rotating files aren't supported");
274.   }
275. 
276.   const stream = streamConfig.stream as BunyanStream;
277.   if (stream?.writable) {
278.     const write = (
279.       chunk: BunyanRecord,
280.       enc: BufferEncoding,
281.       cb: (err?: Error | null) => void,
282.     ): void => {
283.       const raw = sanitizeValue(chunk);
284.       const result =
285.         streamConfig.type === 'raw'
286.           ? raw
287.           : JSON.stringify(raw, bunyan.safeCycles()).replace(
288.               regEx(/\n?$/),
289.               '\n',
290.             );
291.       stream.write(result, enc, cb);
292.     };
293. 
294.     return {
295.       ...streamConfig,
296.       type: 'raw',
297.       stream: { write },
298.     } as bunyan.Stream;
299.   }
300. 
301.   if (streamConfig.path) {
302.     const fileStream = fs.createWriteStream(streamConfig.path, {
303.       flags: 'a',
304.       encoding: 'utf8',
305.     });
306. 
307.     return withSanitizer({ ...streamConfig, stream: fileStream });
308.   }
309. 
310.   throw new Error("Missing 'stream' or 'path' for bunyan stream");
311. }
