313. /**
314.  * A function that terminates execution if the log level that was entered is
315.  *  not a valid value for the Bunyan logger.
316.  * @param logLevelToCheck
317.  * @returns returns the logLevel when the logLevelToCheck is valid or the defaultLevel passed as argument when it is undefined. Else it stops execution.
318.  */
319. export function validateLogLevel(
320.   logLevelToCheck: string | undefined,
321.   defaultLevel: bunyan.LogLevelString,
322. ): bunyan.LogLevelString {
323.   const allowedValues: bunyan.LogLevelString[] = [
324.     'trace',
325.     'debug',
326.     'info',
327.     'warn',
328.     'error',
329.     'fatal',
330.   ];
331. 
332.   if (
333.     isUndefined(logLevelToCheck) ||
334.     (isString(logLevelToCheck) &&
335.       allowedValues.includes(logLevelToCheck as bunyan.LogLevelString))
336.   ) {
337.     // log level is in the allowed values or its undefined
338.     return (logLevelToCheck as bunyan.LogLevelString) ?? defaultLevel;
339.   }
340. 
341.   const logger = bunyan.createLogger({
342.     name: 'renovate',
343.     streams: [
344.       {
345.         level: 'fatal',
346.         stream: process.stdout,
347.       },
348.     ],
349.   });
350.   logger.fatal({ logLevel: logLevelToCheck }, 'Invalid log level');
351.   process.exit(1);
352. }
