354. // Can't use `util/regex` because of circular reference to logger
355. const urlRe = /[a-z]{3,9}:\/\/[^@/]+@[a-z0-9.-]+/gi;
356. const urlCredRe = /\/\/[^@]+@/g;
357. const dataUriCredRe = /^(data:[0-9a-z-]+\/[0-9a-z-]+;).+/i;
