359. export function sanitizeUrls(text: string): string {
360.   return text
361.     .replace(urlRe, (url) => {
362.       return url.replace(urlCredRe, '//**redacted**@');
363.     })
364.     .replace(dataUriCredRe, '$1**redacted**');
365. }
