367. export function getEnv(key: string): string | undefined {
368.   return [process.env[`RENOVATE_${key}`], process.env[key]]
369.     .map((v) => v?.toLowerCase().trim())
370.     .find(isNonEmptyStringAndNotWhitespace);
371. }
372. 
373. export function getMessage(
374.   p1: string | Record<string, any>,
375.   p2?: string,
376. ): string | undefined {
377.   return isString(p1) ? p1 : p2;
378. }
379. 
380. export function toMeta(
381.   p1: string | Record<string, any>,
382. ): Record<string, unknown> {
383.   return isObject(p1) ? p1 : {};
384. }
