332. function isCircular(value: unknown, visited = new Set<unknown>()): boolean {
333.   if (value === null || typeof value !== 'object') {
334.     return false;
335.   }
336. 
337.   if (visited.has(value)) {
338.     return true;
339.   }
340. 
341.   const downstreamVisited = new Set(visited);
342.   downstreamVisited.add(value);
343. 
344.   if (Array.isArray(value)) {
345.     for (const childValue of value) {
346.       if (isCircular(childValue, downstreamVisited)) {
347.         return true;
348.       }
349.     }
350. 
351.     return false;
352.   }
353. 
354.   const values = Object.values(value);
355.   for (const ov of values) {
356.     if (isCircular(ov, downstreamVisited)) {
357.       return true;
358.     }
359.   }
360. 
361.   return false;
362. }
